const dictionaries = { de, en };

export function translate(locale: Locale, key: string, values: Values = {}): string {
  const template = dictionaries[locale][key] ?? dictionaries.de[key] ?? key;
  return Object.entries(values).reduce((text, [name, value]) => text.replaceAll(`{${name}}`, String(value)), template);
}

export function formatNumber(locale: Locale, value: number, options?: Intl.NumberFormatOptions): string {
  return new Intl.NumberFormat(locale === "de" ? "de-DE" : "en-US", options).format(value);
}

export function formatDateTime(locale: Locale, value: string, options?: Intl.DateTimeFormatOptions): string {
  return new Intl.DateTimeFormat(locale === "de" ? "de-DE" : "en-US", {
    timeZone: "Europe/Berlin", dateStyle: "medium", timeStyle: "medium", ...options,
  }).format(new Date(value));
}

interface I18nValue {
  locale: Locale;
  t: (key: string, values?: Values) => string;
  number: (value: number, options?: Intl.NumberFormatOptions) => string;
  dateTime: (value: string, options?: Intl.DateTimeFormatOptions) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ locale, children }: { locale: Locale; children: React.ReactNode }): React.ReactElement {
  const t = (key: string, values: Values = {}): string => translate(locale, key, values);
  const number = (value: number, options?: Intl.NumberFormatOptions): string => formatNumber(locale, value, options);
  const dateTime = (value: string, options?: Intl.DateTimeFormatOptions): string => formatDateTime(locale, value, options);
  return <I18nContext.Provider value={{ locale, t, number, dateTime }}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const value = useContext(I18nContext);
  if (!value) throw new Error("useI18n must be used inside I18nProvider.");
  return value;
}

export function reasonText(t: I18nValue["t"], reason: { titleKey: string; measuredValue?: string | number | null; requiredValue?: string | number | null }): string {
  const base = t(reason.titleKey);
  if (reason.measuredValue == null && reason.requiredValue == null) return base;
  if (reason.requiredValue == null) return `${base}: ${reason.measuredValue}`;
  return `${base}: ${reason.measuredValue ?? "–"} / ${reason.requiredValue}`;
}

export function statusText(t: I18nValue["t"], status: unknown): string {
  const value = String(status ?? "");
  return t(`status.${value}`);
}
